651	const gated = (runs: number) => {
652	  const sent: OutgoingMessage[] = [];
653	  const socket = {
654	    readyState: WebSocket.OPEN as number,
655	    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
656	  };
657	  const ws = socket as unknown as WebSocket;
658	  const gates = Array.from({length: runs}, () => deferred());
659	  const handed: SessionEntry[][] = [];
660	  const processMessageStream = async function* (session: ChatSession): AsyncGenerator<MessageChunk> {
661	    const run = handed.length;
662	    handed.push(structuredClone(session.entries));
663	    yield text(`answer ${run}`);
664	    await gates[run].until;
665	    yield STOP;
666	  };
667	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
668	  const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator);
669	
670	  return {
671	    session,
672	    handed,
673	    release: (run: number) => gates[run].release(),
674	    close: () => {
675	      socket.readyState = WebSocket.CLOSED;
676	    },
677	    frames: () => wire(sent),
678	    send: (raw: unknown) => handle(ws, session, raw),
679	  };
680	};

